"""Bind the publication narrative to the final frozen economic result files."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
rows = json.loads((ROOT / "economics/results/confirmation.json").read_text())["rows"]
results = {row["scenario"]: row for row in rows}
baseline = results["baseline"]
assert round(baseline["operating_profit"], 2) == -809.68
assert baseline["repetitions"] == 600
assert json.loads((ROOT / "economics/policy_frozen.json").read_text())["price"] == 800

replacement = {
    "ABSTRACT_ECON": "A corrected, cost-anchored 90-day scenario model selects USD 800 as the best of seven tested success fees, but rejects launch. Fresh confirmation yields mean operating loss USD 810 in the baseline, with a 69% modeled loss frequency; low and high scenarios yield approximately −USD 2,377 and +USD 6,283. No tested source-effort/outside-option cell is robustly profitable across the declared adverse corners. These are conditional simulations with unvalidated demand and source-work assumptions, not earned revenue. Actual collections are zero and complete actual research expenditure is unknown.",
    "ECON_CORRECTIONS": "The final version includes USD 5 cash acquisition spend per originating opportunity, with USD 0/15/50 sensitivities; acquisition labor remains separately charged through intake and fixed duties. A 20% assumed rework event adds one bounded developer/domain round and another USD 0.37 tool allowance. A separate 5% budget-exhaustion event forces refusal and refund. This provider-specific risk lowers offer reliability without weakening the human alternative. The eligible baseline probabilities are q_offer = 0.460275 and q_H = 0.4845.\n\nThe correction history matters. An early scheduler used an unobserved failure outcome to free a slot; its exploratory record is preserved. A later zero-demand reporting error interrupted a completed simulation and was separately recorded. Independent audit then identified missing acquisition cash, queue-aware deposit finance, pending fees and bounded correction. The earlier USD 466.82 positive baseline is therefore incomplete and superseded. The final v2.1 policy uses new exploration and confirmation seeds, preserves the old results, and removes an additional unjustified penalty to the human comparator before final confirmation. The audit is available alongside the frozen files.",
    "ECON_RESULTS": "The final exploratory means are negative at every tested price. USD 800 is the best tested quote at approximately −USD 852 per 90-day baseline campaign, and the launch gate is false. Fresh confirmation retains that price without retuning. Each scenario below averages 600 campaigns.\n\n| Scenario | Origins | Contracts | Accepted original queries by day 90 | Earned modeled revenue | Operating profit | Modeled loss frequency |\n|---|---:|---:|---:|---:|---:|---:|\n| Low | 60 | 1.29 | 0.23 | USD 176 | −USD 2,377 | 100% |\n| Baseline | 150 | 23.59 | 9.165 | USD 7,116 | −USD 810 | 69.0% |\n| High | 300 | 48.69 | 21.86 | USD 17,147 | +USD 6,283 | 0.5% |\n\nThe baseline mean-profit Monte Carlo interval is −USD 951 to −USD 668; the 10th–90th percentile campaign outcomes are −USD 3,030 to +USD 1,432. The high case demonstrates a conditional positive scenario, not a verified market. It assumes better source fit and acceptance, lower source effort and greater buyer value. Capacity rejects about 19.67 otherwise willing high-case origins, while 14.03 contracts remain open at day 90. Demand and delivery are finite.\n\nFor comparison, raising the quote from USD 800 to USD 1,000 reduces exploratory expected contracts from 23.41 to 9.45 and worsens mean profit from −USD 852 to −USD 1,514. Lowering it to USD 150 produces about 61.52 contracts but a loss of USD 8,931. This is a tested decision policy under specified assumptions, not a globally optimal real-world price.",
    "CASH_RESULTS": "The baseline campaign's average accounting is explicit:\n\n| Baseline quantity | Modeled USD | Meaning |\n|---|---:|---|\n| Gross customer cash collected | 11,664.80 | Includes deposits, including unfinished work. |\n| Cash refunds | 3,667.20 | Includes returned unsuccessful-delivery deposits. |\n| Net customer cash collected | 7,997.60 | Receipts less cash refunds; still not earned revenue. |\n| Earned revenue after refund allowances | 7,115.56 | Accepted original-query fees, adjusted for refunds. |\n| Direct variable A costs | 6,245.45 | Includes acquisition, all-origin intake, failed attempts and variable overhead. |\n| Bad debt | 106.34 | Uncollected accepted balances, adjusted for refunds. |\n| Contribution | 763.78 | Earned revenue less variable A costs and bad debt. |\n| Fixed campaign cost with its overhead | 1,572.95 | Charged once, after contribution. |\n| Financing | 0.52 | Interest on temporary borrowing. |\n| Operating profit | −809.68 | Forward campaign result, before B or sunk C. |\n\nAt day 90, modeled cash on hand is USD 5,746.50. It includes owner funding. Restricted deposits are USD 1,120; refund-window reserves USD 1,157.60; payables USD 493.12; remaining completion budget USD 634.37; additional conditional fee buffer USD 0.66; and debt USD 74.69. Pending payment fees of USD 5.30 are already part of payables. Free funds after those restrictions average USD 2,266.06, including remaining initial owner capital. They are not profit. The baseline 95th-percentile temporary borrowing need is USD 1,184.13, within the assumed USD 20,000 limit in the modeled runs. The unselected first confirmation ledger and cash identity checks are retained.",
    "ROBUSTNESS_RESULTS": "The robustness grid crosses source construction-plus-validation effort of 0.5/1/2/4 hours with competent outside analysis effort of 30/90/180 minutes. Each of the 12 cells is tested at the frozen quote against baseline, reduced admissibility/decisiveness, higher refund/default, lower value and combined adverse corners. A robust cell requires every corner's lower Monte Carlo mean-profit bound to be positive and its financing requirement to remain within the stated limit. **Zero of 12 cells qualifies.** Even the 0.5-hour, 180-minute cell loses about USD 1,615 in its worst declared corner.\n\nAcquisition alone is consequential. The final baseline with zero cash acquisition still averages −USD 59; USD 15 per origin gives −USD 2,312; USD 50 gives −USD 7,604. A competent human alternative requiring only ten additional analysis minutes produces essentially no demand and approximately −USD 2,839. These stresses are separate from E = U; customers can value outsourcing without any expert-agent superiority.\n\nCustomer value and savings are not assumed to equal human R&D expenditure. In the baseline, the independently assumed median value of a decisive outcome is USD 800, and customer time is valued at USD 120/hour. At median complexity, zero queue wait and the USD 800 quote, the minimum outcome value needed to prefer the offer to doing nothing is approximately USD 854.43. At a USD 900 outcome value and 1.05 source-work hours, about 125.20 minutes of additional competent-human analysis must be avoidable to match the outside option. These are participation thresholds, not measured savings. Higher source burden may increase outsourcing demand while simultaneously making the supplier unprofitable.\n\nThe success fee places non-delivery risk on the supplier; objective source and query acceptance conditions reduce the incentive to substitute an easy answer. The model treats refunds and default as explicit exogenous risks, not a solved strategic equilibrium. It does not validate protection against opportunistic refund claims, adversarial source submission or competitors changing price. Those information and incentive problems belong in a live pilot before a commercial commitment.\n\nSunk C sensitivities of USD 0/5,000/15,000/50,000/100,000 are reported separately. The high operating case remains approximately +USD 1,283 after USD 5,000 of development, but becomes −USD 8,717 after USD 15,000. C = 0 is the forward operating comparison, not a claim that research was free. Rejected discovery candidates and unpaid construction remain part of actual unknown research expense.",
    "CONCLUSION_ECON": "The strongest positive commercial scenario yields about USD 6,283 over 90 days before sunk development. It coexists with a baseline operating loss, a rejected launch gate and an empty robust profitable region. Complete actual research cost is unknown and no customer cash was collected. This edition therefore establishes neither a viable flagship venture nor a self-financing learning loop. It provides a decision model that can reject an attractive-looking opportunity when acquisition, source obligations and a competent outside option are included.",
    "ECON_REPRO": "For a clean complete reproduction, the included wrapper stages minimal inputs in a new literal `study/` directory, runs the construction and final economics, and compares deterministic evidence:\n\n```\npython study/reproduce.py --out /tmp/alpha-flywheel-reproduction\n```\n\nThe economics runner's sequential commands are `check`, `explore`, `confirm`, `robustness` and `supplementary`. Its final exploration seed is 271028401 and confirmation seed 271029987. Existing outputs and frozen policies are intentionally not overwritten. The wrapper preserves command logs and a comparison receipt; timing-only differences are outside exact-byte acceptance. Historical failed versions are retained for inspection and are not substituted for the current model.",
}

text = (ROOT / "manuscript.template.md").read_text()
for key, value in replacement.items():
    assert f"@@{key}@@" in text
    text = text.replace(f"@@{key}@@", value)
assert "@@" not in text
text = text.replace("No tokens, funds or live network permissions were used.", "No blockchain tokens, funds or live network permissions were used.")
text = text.replace("Toussaint, M.,", "Toussaint, E.,")
text = text.replace("Zhang, R. and Sieber, R.", "Zhang, Y. and Sieber, R. E.")
text = text.replace("An additional independently uncertain period offset of amplitude 0.0125 also consumes the margin.", "Allowing an additional offset of ±0.0125 independently in each of the two periods also consumes the 0.025 margin; an offset in only one period would need amplitude 0.025.")
text = text.replace("An independence-relaxed interval control", "A control with calibration varied independently by row")
text = text.replace("an independence-relaxed interval control", "a control with calibration varied independently by row")
text = text.replace("The eligible baseline probabilities", "The eligible baseline probabilities")
text = text.replace("The probability used by an already eligible buyer is the product of the last three.", "The human outside option uses the product of the last three; provider reliability is additionally reduced by the budget-exhaustion probability described below.")
text = text.replace("For each potential buyer, q is the assumed probability of source admissibility, original-query decisiveness and acceptance.", "For each potential buyer, q_offer and q_H separately represent the assumed acceptance probabilities for the offer and human alternative.")
text = text.replace("The buyer compares q × (value − success fee)", "The buyer compares q_offer × (value − success fee)")
text = text.replace("against the better of no purchase and a human/self-service alternative.", "against the better of no purchase and a human/self-service alternative valued with q_H.")
text = text.replace("Relaxing shared calibration to independent row intervals resolves six.", "Varying calibration independently by row, while retaining the same sparse-error budget, resolves six.")
text = text.replace("This ablation shows the value of retaining dependence", "This ablation changes only calibration dependence and shows the value of retaining it")
text = text.replace("Planning success probabilities of 0.20/0.50/0.80 and elapsed durations are hypotheses to elicit, not observed human performance.", "Planning success probabilities of 0.20/0.50/0.80 are hypotheses to elicit, not observed human performance. Illustrative elapsed durations are 1/3/8 weeks for the narrow demonstrator and 2/5/12 months for source-verified deployment; access and review can dominate calendar time. These duration assumptions do not measure an AI speed advantage.")
text = text.replace("It is an investment proposal, not an executed study or a claim that 12 cases establish broad performance.", "The accompanying plan caps this optional, unfunded research proposal at approximately USD 5,100, including 38 assumed professional hours, source/tool allowances and contingency. It is not an executed study or a claim that 12 cases establish broad performance.")
text = text.replace("Confirmation code and policy freezes precede their fresh cases or random seeds.", "Scientific source freezes precede case generation, and economic policy freezes precede execution of the confirmation seed. Seed values themselves were already specified and available.")
text = text.replace("duplicate identifiers, missing source labels", "duplicate row or group identifiers, missing source labels")
text = text.replace("special retention advantage is absent in this control.", "no output-quality advantage from the special package is observed in this control; broader retrieval or maintenance value is unmeasured.")
text = text.replace("Chemistry source and raw candidate attribution are retained in the expert search record.", "The chemistry comparison uses MCheM [21]; raw candidate attribution is retained in the expert search record.")
text = text.replace("\n**Research disclosure.**", "\n21. Vitale, G. A., Xia, S. N., Dührkop, K. and colleagues (2025). **Enhancing tandem mass spectrometry-based metabolite annotation with online chemical labeling.** Nature Communications 16, 6911. [Primary article](https://www.nature.com/articles/s41467-025-61240-z); [open full text](https://pmc.ncbi.nlm.nih.gov/articles/PMC12297239/).\n\n**Research disclosure.**")
text = text.replace("The full project also bears C, the unpaid development and search expense.", "Operating profit is before income tax. Modeled free funds account for the listed scenario obligations, not actual tax liabilities or an approved growth budget. The full project also bears C, the unpaid development and search expense.")
(ROOT / "manuscript.md").write_text(text)
print(f"Wrote manuscript.md: {len(text.split())} words")
